fn solve(n: i8, k: i8) -> i8 {
    // Compute the remainder r = n mod k. Since n >= 0 and k > 0,
    // Rust's `%` gives a nonnegative remainder in [0, k-1].
    let r = n % k;
    // The distance to the next multiple "above" n is k - r.
    let dist_up = k - r;
    // Return the smaller of stepping down by r or stepping up by k - r.
    r.min(dist_up)
}

